    pagedScript.src = '/assets/paged.polyfill.min.js';
    pagedScript.onerror = function() {
      try { parent.postMessage({ source: 'sonde-paged', type: 'fallback' }, '*'); } catch (e) {}
      if (printFrameCancelled) return;
      window.print();
    };
